CREATE TABLE IF NOT EXISTS categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,slug VARCHAR(140) NOT NULL UNIQUE,min_age TINYINT UNSIGNED NULL,max_age TINYINT UNSIGNED NULL,display_order INT NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS seasons (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,year SMALLINT UNSIGNED NULL,starts_at DATE NULL,ends_at DATE NULL,display_order INT NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tournament_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,category_id BIGINT UNSIGNED NOT NULL,season_id BIGINT UNSIGNED NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,UNIQUE KEY tournament_category_season(tournament_id,category_id,season_id),FOREIGN KEY(tournament_id) REFERENCES tournaments(id),FOREIGN KEY(category_id) REFERENCES categories(id),FOREIGN KEY(season_id) REFERENCES seasons(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tournament_assets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,asset_type VARCHAR(40) NOT NULL,file_path VARCHAR(255) NOT NULL,alt_text VARCHAR(180) NULL,display_order INT NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL DEFAULT 'active',starts_at DATETIME NULL,ends_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(tournament_id) REFERENCES tournaments(id),INDEX(tournament_id,asset_type,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sponsors (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,logo_path VARCHAR(255) NULL,link_url VARCHAR(255) NULL,sponsor_type VARCHAR(60) NULL,display_order INT NOT NULL DEFAULT 0,starts_at DATETIME NULL,ends_at DATETIME NULL,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(tournament_id) REFERENCES tournaments(id),INDEX(tournament_id,status,display_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tournament_rule_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,version_number INT UNSIGNED NOT NULL,settings_json JSON NOT NULL,change_reason TEXT NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 0,created_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,UNIQUE KEY tournament_version(tournament_id,version_number),FOREIGN KEY(tournament_id) REFERENCES tournaments(id),FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,INDEX(tournament_id,is_active)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ALTER TABLE tournament_themes ADD COLUMN default_theme VARCHAR(10) NOT NULL DEFAULT 'light' AFTER dark_enabled;
